    <thead>
      <tr style="background:#2a2a3a; color:#fff;">
        <th style="padding:8px; border:1px solid #444;">Aspect</th>
        <th style="padding:8px; border:1px solid #444;">1857 Revolt</th>
        <th style="padding:8px; border:1px solid #444;">Later Nationalist Movements</th>
      </tr>
    </thead>
